import{_ as o,o as e,c as a,a5 as i}from"./chunks/framework.D47SInms.js";const p=JSON.parse('{"title":"Robot drifts to one side","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/robot-drifts.md","filePath":"manual/troubleshooting/robot-drifts.md","lastUpdated":1791600043000}'),n={name:"manual/troubleshooting/robot-drifts.md"};function r(s,t,l,h,d,c){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="robot-drifts-to-one-side" tabindex="-1">Robot drifts to one side <a class="header-anchor" href="#robot-drifts-to-one-side" aria-label="Permalink to &quot;Robot drifts to one side&quot;">​</a></h1><p>You command the robot to walk straight and it veers to one side, or its body looks tilted while standing. There is no single cause, so work through the steps <strong>in order</strong> — the earlier ones are both more common and quicker to check.</p><h2 id="floor-and-pose" tabindex="-1">1. Floor and initial pose <a class="header-anchor" href="#floor-and-pose" aria-label="Permalink to &quot;1. Floor and initial pose {#floor-and-pose}&quot;">​</a></h2><p><strong>Cause:</strong> On a sloped or slippery floor the robot drifts sideways. Starting from an initial pose that is not left-right symmetric has the same effect.</p><p><strong>Fix:</strong> Try again on a flat, solid floor. Before switching the power on, check that the legs are folded symmetrically.</p><p><strong>→ <a href="/RBQ/nightly/manual/operation/initial-pose.html">Initial Pose</a></strong></p><h2 id="payload" tabindex="-1">2. Payload configuration <a class="header-anchor" href="#payload" aria-label="Permalink to &quot;2. Payload configuration {#payload}&quot;">​</a></h2><p><strong>Cause:</strong> If equipment is mounted on the robot but its mass and position were never entered — or entered incorrectly — the robot miscalculates its center of mass and drifts. Leftover values after removing equipment cause the same problem.</p><p><strong>Fix:</strong> Check that the configured values match what is actually mounted, and re-enter them if they differ. If all equipment has been removed, reset the values.</p><p><strong>→ <a href="/RBQ/nightly/manual/troubleshooting/payload_setting.html">Payload configuration</a></strong></p><h2 id="zmp" tabindex="-1">3. ZMP calibration <a class="header-anchor" href="#zmp" aria-label="Permalink to &quot;3. ZMP calibration {#zmp}&quot;">​</a></h2><p><strong>Cause:</strong> If the center of ground reaction force is off while the robot stands, it keeps leaning to one side while walking too. This is the item that acts most directly on drift.</p><p><strong>Fix:</strong> Run ZMP calibration again, on a flat solid floor with nothing mounted on the robot.</p><p><strong>→ <a href="/RBQ/nightly/manual/troubleshooting/calibration-tuning.html">Calibration &amp; Tuning</a></strong></p><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p>Do not push the robot or place objects on it during calibration. Calibrating in that state makes the drift worse.</p></div></div><h2 id="leg-module" tabindex="-1">4. Leg module condition <a class="header-anchor" href="#leg-module" aria-label="Permalink to &quot;4. Leg module condition {#leg-module}&quot;">​</a></h2><p><strong>Cause:</strong> A leg module or foot that has worked loose or worn down pushes the robot that way.</p><p><strong>Fix:</strong> Sit the robot down, switch the power off, then check by hand whether any leg has play and whether one foot pad is noticeably more worn than the others.</p><p><strong>→ <a href="/RBQ/nightly/manual/maintenance/leg-module.html">Leg Module</a> · <a href="/RBQ/nightly/manual/maintenance/foot.html">Foot</a></strong></p><h2 id="still-stuck" tabindex="-1">Still stuck? <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck? {#still-stuck}&quot;">​</a></h2><p>Tell us how far through steps 1–4 you got, along with:</p><ul><li>which direction it drifts (left, right, forward, backward)</li><li>whether it is already tilted while standing, or only drifts while walking</li><li>whether it only happens in a particular gait mode</li></ul><p><strong>→ <a href="/RBQ/nightly/manual/support/">Contact us</a></strong></p>',23)])])}const g=o(n,[["render",r]]);export{p as __pageData,g as default};
